local _, addon = ...
addon.localeData.frFR.texts = {
    FIREBALL = { name = "Boule de feu", ziel = { "Sentez la chaleur, %s !", "*lance Boule de feu sur %s.*", "%s, votre armure ne remplacera jamais une protection contre le feu." }, gruppe = { "Sentez la chaleur !", "*incante Boule de feu.*", "La flamme obéit à ma main, pas à mon humeur.", "*referme les doigts sur un noyau incandescent avant de le projeter.*", "Une boule de feu est une promesse de flammes qu'on ne retire pas.", "*tend des fils incandescents jusqu'à ce qu'ils s'animent d'eux-mêmes.*" } },
    FROSTBOLT = { name = "Éclair de givre", ziel = { "Un salut glacé, %s !", "*lance Éclair de givre sur %s.*", "%s, chacun de vos pas sera désormais plus pénible." }, gruppe = { "Un salut glacé !", "*incante Éclair de givre.*", "L'hiver n'attend aucune invitation.", "*arrache un éclat de glace acéré à l'air humide.*", "Un éclat de givre suffit à refroidir les ardeurs.", "*expire lentement, dessinant des lignes de cristaux argentés dans l'air.*" } },
    ARCANE_MISSILES = { name = "Projectiles des Arcanes", ziel = { "Les énergies arcaniques vous cherchent, %s !", "*lance Projectiles des Arcanes sur %s.*", "%s, cinq pensées pour une seule cible." }, gruppe = { "Les énergies arcaniques vous cherchent !", "*incante Projectiles des Arcanes.*", "Les projectiles trouveront leur chemin à travers le chaos.", "*divise un fil de lumière violette en étincelles guidées.*", "Chaque projectile suit sa rune, mais tous convergent vers le même point.", "*décale un glyphe flottant d'un cheveu et en écoute le bourdonnement.*" } },
    FIRE_BLAST = { name = "Trait de feu", ziel = { "Une étincelle suffit, %s !", "*lance Trait de feu sur %s.*", "%s, inutile de vous infliger un long discours." }, gruppe = { "Une étincelle suffit !", "*incante Trait de feu.*", "Un instant suffit quand l'étincelle est bien placée.", "*claque des doigts et embrase l'air dans un bruit sec.*", "Un claquement de doigts, une déflagration, et adieu les sourcils.", "*tend des fils incandescents jusqu'à ce qu'ils s'animent d'eux-mêmes.*" } },
    PYROBLAST = { name = "Explosion pyrotechnique", ziel = { "Place au grand brasier, %s !", "*lance Explosion pyrotechnique sur %s.*", "%s, cet enchantement mérite qu'on garde ses distances." }, gruppe = { "Place au grand brasier !", "*incante Explosion pyrotechnique.*", "Les grandes flammes exigent une main sûre.", "*trace un vaste cercle de feu et le condense en une sphère rugissante.*", "Cette flamme prend son temps pour grandir et ne laisse aucun refuge.", "*tend des fils incandescents jusqu'à ce qu'ils s'animent d'eux-mêmes.*" } },
    FLAMESTRIKE = { name = "Choc de flammes", ziel = { "Le sol lui-même brûlera !", "*lance Choc de flammes sur %s.*", "%s, surveillez plutôt l'endroit où vous posez les pieds." }, gruppe = { "Le sol lui-même brûlera !", "*incante Choc de flammes.*", "Le sol se souvient de chaque sceau mal placé.", "*dessine un motif ardent sous les pieds de ses adversaires.*", "Le sol reçoit un sceau, puis le feu s'abat sur lui.", "*tend des fils incandescents jusqu'à ce qu'ils s'animent d'eux-mêmes.*" } },
    SCORCH = { name = "Brûlure", ziel = { "Un avant-goût du feu, %s.", "*lance Brûlure sur %s.*", "%s, petite leçon de chaleur appliquée." }, gruppe = { "Un avant-goût du feu.", "*incante Brûlure.*", "Toute flamme n'a pas vocation à devenir un brasier.", "*passe deux doigts dans l'air et laisse une fine traînée de braises.*", "Une étincelle vive vaut parfois mieux qu'un grand brasier.", "*tend des fils incandescents jusqu'à ce qu'ils s'animent d'eux-mêmes.*" } },
    BLIZZARD = { name = "Blizzard", ziel = { "L'hiver est sans pitié !", "*lance Blizzard sur %s.*", "%s, vous feriez mieux de trouver un abri chaud." }, gruppe = { "L'hiver est sans pitié !", "*incante Blizzard.*", "Quand le ciel se tait, la neige prend la parole.", "*lève les bras et invoque une bourrasque de neige et de glace tranchante.*", "Le ciel blanchit bien avant que le premier ennemi ne tremble.", "*expire lentement, dessinant des lignes de cristaux argentés dans l'air.*" } },
    FROST_NOVA = { name = "Nova de givre", ziel = { "Pas un pas de plus, %s !", "*lance Nova de givre sur %s.*", "%s, votre élan s'arrête ici." }, gruppe = { "Pas un pas de plus !", "*incante Nova de givre.*", "Le froid trace une frontière impossible à ignorer.", "*abaisse la paume vers le sol et répand le givre tout autour.*", "Un cercle de givre indique clairement où vous allez rester.", "*expire lentement, dessinant des lignes de cristaux argentés dans l'air.*" } },
    CONE_OF_COLD = { name = "Cône de froid", ziel = { "Un souffle du nord !", "*lance Cône de froid sur %s.*", "%s, l'air de l'hiver vient à votre rencontre." }, gruppe = { "Un souffle du nord !", "*incante Cône de froid.*", "Un souffle suffit à rendre les environs bien peu accueillants.", "*écarte les doigts et projette devant soi une vague d'air glacial.*", "Un souffle glacé, assez large pour surprendre toute une rangée.", "*expire lentement, dessinant des lignes de cristaux argentés dans l'air.*" } },
    ICE_BARRIER = { name = "Barrière de glace", ziel = {  }, gruppe = { "Le froid est mon bouclier.", "*incante Barrière de glace.*", "Mon bouclier est tissé de patience et de givre.", "*superpose de fins cristaux de glace autour de son corps.*", "Chaque couche de glace m'offre une seconde de plus.", "*referme un cercle protecteur scintillant d'une syllabe murmurée.*" } },
    ICE_BLOCK = { name = "Bloc de glace", ziel = {  }, gruppe = { "Je suis momentanément indisponible.", "*incante Bloc de glace.*", "Certaines attaques ne méritent aucune réplique, seulement une pause.", "*ferme les yeux tandis qu'une gangue de glace translucide se forme.*", "Parfois, la meilleure réponse est un instant parfaitement immobile.", "*referme un cercle protecteur scintillant d'une syllabe murmurée.*" } },
    ARCANE_EXPLOSION = { name = "Explosion des Arcanes", ziel = { "Reculez, la magie s'agite !", "*lance Explosion des Arcanes sur %s.*", "%s, quittez mon cercle d'incantation." }, gruppe = { "Reculez, la magie s'agite !", "*incante Explosion des Arcanes.*", "La distance est parfois la plus sage des disciplines arcaniques.", "*écarte brusquement les bras et libère un anneau d'énergie violette.*", "L'énergie est partout avant même qu'on distingue le cercle.", "*décale un glyphe flottant d'un cheveu et en écoute le bourdonnement.*" } },
    COUNTERSPELL = { name = "Contresort", ziel = { "Votre incantation s'arrête ici, %s !", "*lance Contresort sur %s.*", "%s, vos syllabes sont mal placées." }, gruppe = { "Votre incantation s'arrête ici !", "*incante Contresort.*", "Il suffit de dérober une syllabe pour briser un sort.", "*coupe net une incantation ennemie d'un geste de deux doigts.*", "Une syllabe de trop, et votre sort se dissout dans le silence.", "*décale un glyphe flottant d'un cheveu et en écoute le bourdonnement.*" } },
    POLYMORPH = { name = "Métamorphose", ziel = { "Un peu de laine vous va bien, %s.", "*lance Métamorphose sur %s.*", "%s, vous me sembliez bien plus grand il y a un instant." }, gruppe = { "Un peu de laine vous va bien.", "*incante Métamorphose.*", "Un peu de laine vous irait bien.", "*esquisse la silhouette d'un mouton.*", "Un peu d'humilité, quatre sabots et beaucoup de laine.", "*dessine un mouton de lumière dont la silhouette enveloppe la cible.*", "La métamorphose est un art précis ; la laine n'est qu'un détail.", "*examine les contours du sort à la recherche de cornes imprévues.*", "Changer de forme un instant peut se montrer fort persuasif.", "Une autre forme peut changer radicalement le point de vue.", "*tourne une rune et observe les contours se modifier.*" } },
    BLINK = { name = "Transfert", ziel = {  }, gruppe = { "Un instant, je serai ailleurs.", "*incante Transfert.*", "Le chemin le plus court n'est pas toujours celui qu'on voit.", "*disparaît dans une mince fente de lumière bleue et réapparaît un battement de cœur plus tard.*", "L'espace entre deux pas n'est qu'une affaire d'entraînement.", "*oriente vers la lumière les coordonnées d'une carte flottante.*" } },
    SLOW_FALL = { name = "Chute lente", ziel = { "La gravité attendra aujourd'hui.", "*lance Chute lente sur %s.*", "La gravité fera une exception aujourd'hui.", "*dessine un arc léger comme une plume sous les bottes de %s.*" }, gruppe = { "La gravité attendra aujourd'hui.", "*incante Chute lente.*", "La gravité fera une exception aujourd'hui.", "*dessine un arc léger comme une plume sous ses bottes.*", "La gravité attendra son tour un instant.", "*oriente vers la lumière les coordonnées d'une carte flottante.*" } },
    EVOCATION = { name = "Évocation", ziel = {  }, gruppe = { "Un instant pour rassembler mes pensées et mon mana.", "*incante Évocation.*", "Même les grands arts ont parfois besoin de reprendre leur souffle.", "*ramène lentement des étincelles de mana vers ses paumes.*", "Le mana revient quand je cesse de disperser ses courants.", "*décale un glyphe flottant d'un cheveu et en écoute le bourdonnement.*" } },
    ARCANE_INTELLECT = { name = "Intelligence des Arcanes", ziel = { "Un esprit vif est votre meilleure arme, %s.", "*lance Intelligence des Arcanes sur %s.*", "%s, que votre esprit soit plus aiguisé que votre lame." }, gruppe = { "Un esprit vif est votre meilleure arme.", "*incante Intelligence des Arcanes.*", "Un esprit alerte est le plus fiable des talismans.", "*pose un petit glyphe lumineux contre sa tempe.*", "Une pensée plus vive vaut mieux qu'une lame plus affûtée.", "*dépose un fil magique lumineux sur sa paume ouverte.*" } },
    ARCANE_BRILLIANCE = { name = "Illumination des Arcanes", ziel = { "Que nos esprits brillent davantage !", "*lance Illumination des Arcanes sur %s.*", "%s, le savoir gagne à être partagé." }, gruppe = { "Que nos esprits brillent davantage !", "*incante Illumination des Arcanes.*", "Les meilleurs compagnons sont ceux qui réfléchissent ensemble.", "*déploie un réseau de runes lumineuses sur ses alliés.*", "Un cercle d'esprits éveillés surpasse un génie solitaire.", "*dépose un fil magique lumineux sur sa paume ouverte.*" } },
    MANA_SHIELD = { name = "Bouclier de mana", ziel = {  }, gruppe = { "Le mana me protège, la pensée devient acier.", "*incante Bouclier de mana.*", "Mes pensées sont plus difficiles à percer que ma robe.", "*enroule des fils de mana autour de ses épaules.*", "Je préfère dépenser mon mana que sacrifier ma dernière robe.", "*referme un cercle protecteur scintillant d'une syllabe murmurée.*" } },
    CONJURE_FOOD = { name = "Invocation de nourriture", ziel = {  }, gruppe = { "Un peu de magie contre la faim.", "*incante Invocation de nourriture.*", "La bonne magie sait aussi apaiser la faim.", "*ouvre les mains et fait apparaître une collation encore parfumée.*", "Le grand art de la magie devrait aussi satisfaire l'estomac.", "*rassemble des étincelles éparses en une forme presque tangible.*" } },
    CONJURE_WATER = { name = "Invocation d'eau", ziel = {  }, gruppe = { "De l'eau fraîche, née de la magie.", "*incante Invocation d'eau.*", "Buvez. L'étude des arcanes donne soif.", "*attrape une goutte de lumière et la transforme en eau limpide.*", "Une goutte née de rien, et le voyage devient supportable.", "*rassemble des étincelles éparses en une forme presque tangible.*" } },
    CREATE_MANA_GEM = { name = "Invocation d'une gemme de mana", ziel = {  }, gruppe = { "Une petite réserve pour les urgences.", "*incante Invocation d'une gemme de mana.*", "Une petite réserve pour un gros problème.", "*condense du mana vacillant en une gemme froide et lumineuse.*", "Un petit cristal, soigneusement chargé d'énergie de réserve.", "*rassemble des étincelles éparses en une forme presque tangible.*" } },
    PORTAL = { name = "Portail", ziel = {  }, gruppe = { "Attention à vos membres en traversant.", "*incante Portail.*", "Quiconque franchit ce seuil doit se fier au cercle de destination.", "*ouvre avec précaution un pli circulaire dans le tissu de l'espace.*", "Un passage n'est utile que si sa sortie se trouve au bon endroit.", "*oriente vers la lumière les coordonnées d'une carte flottante.*" } },
    TELEPORT = { name = "Téléportation", ziel = {  }, gruppe = { "Je prends un raccourci à travers l'espace.", "*incante Téléportation.*", "Un pas, une erreur de coordonnées, mille lieues d'écart.", "*trace la rune de destination et se dissout dans un tourbillon de lumière.*", "Je replie la distance au lieu de la parcourir.", "*oriente vers la lumière les coordonnées d'une carte flottante.*" } },
    REMOVE_LESSER_CURSE = { name = "Délivrance de la malédiction mineure", ziel = { "Cette malédiction n'a pas sa place ici, %s.", "*lance Délivrance de la malédiction mineure sur %s.*", "%s, cette malédiction s'est assez longtemps accrochée à vous." }, gruppe = { "Cette malédiction n'a pas sa place ici.", "*incante Délivrance de la malédiction mineure.*", "Aucun enchantement ne résiste à qui sait en défaire les nœuds.", "*détache une ombre d'une épaule à l'aide d'une rune lumineuse.*", "Chaque malédiction a un nœud, et je sais où le défaire.", "*dépose un fil magique lumineux sur sa paume ouverte.*" } },
    DETECT_MAGIC = { name = "Détection de la magie", ziel = { "Voyons quels secrets vous portez, %s.", "*lance Détection de la magie sur %s.*", "%s, votre aura en dit plus long que vos paroles." }, gruppe = { "Voyons quels secrets vous portez.", "*incante Détection de la magie.*", "Les courants cachés laissent toujours une trace.", "*tend un sceau scintillant vers la lumière et observe sa réaction.*", "Les fils invisibles révèlent parfois plus que les armures brillantes.", "*décale un glyphe flottant d'un cheveu et en écoute le bourdonnement.*" } },
    DAMPEN_MAGIC = { name = "Atténuation de la magie", ziel = { "%s, un peu moins de vacarme magique vous fera du bien.", "Toute puissance n'a pas besoin de parler à pleine voix.", "*dépose un voile argenté sur les courants de mana palpitants.*", "%s, apaisons la magie qui tourbillonne autour de vous." }, gruppe = { "Toute puissance n'a pas besoin de parler à pleine voix.", "*dépose un voile argenté sur les courants de mana palpitants.*", "J'apaise le courant avant qu'il ne devienne un torrent.", "*dépose un fil magique lumineux sur sa paume ouverte.*" } },
    AMPLIFY_MAGIC = { name = "Amplification de la magie", ziel = { "%s, j'ouvre vos sens à des courants plus puissants.", "Un surcroît de pouvoir n'est un cadeau que si on sait le guider.", "*élargit d'un geste mesuré le cercle lumineux autour d'un allié.*", "%s, préparez-vous à recevoir un courant magique plus puissant." }, gruppe = { "Un surcroît de pouvoir n'est un cadeau que si on sait le guider.", "*élargit d'un geste mesuré le cercle lumineux autour d'un allié.*", "Un peu plus de résonance, à condition de garder la main ferme.", "*dépose un fil magique lumineux sur sa paume ouverte.*" } },
    FROST_ARMOR = { name = "Armure de givre", ziel = {  }, gruppe = { "Une tête froide mérite une armure à sa mesure.", "*dessine un liseré de givre scintillant autour de ses épaules et de ses bras.*", "Un manteau de froid ne laisse aucune couture sans garde.", "*referme un cercle protecteur scintillant d'une syllabe murmurée.*" } },
    ICE_ARMOR = { name = "Armure de glace", ziel = {  }, gruppe = { "Quiconque me touchera devra d'abord saluer l'hiver.", "*fait croître des écailles de glace dure sur sa robe.*", "La glace épouse le corps, légère comme l'étoffe et dure comme la pierre.", "*referme un cercle protecteur scintillant d'une syllabe murmurée.*" } },
    MAGE_ARMOR = { name = "Armure du mage", ziel = {  }, gruppe = { "La discipline des arcanes commence juste sous ma robe.", "*fait scintiller une couche presque invisible de glyphes protecteurs.*", "Les motifs arcaniques protègent mieux lorsque leurs lignes s'imbriquent.", "*referme un cercle protecteur scintillant d'une syllabe murmurée.*" } },
    FIRE_WARD = { name = "Gardien de feu", ziel = {  }, gruppe = { "Le feu reconnaît le feu, mais toute flamme ne peut franchir ce seuil.", "*referme un anneau d'or incandescent en sceau protecteur.*", "Le feu est bienvenu tant qu'il reste de l'autre côté.", "*referme un cercle protecteur scintillant d'une syllabe murmurée.*" } },
    FROST_WARD = { name = "Gardien de givre", ziel = {  }, gruppe = { "L'hiver frappe. Ma réponse est déjà prête.", "*dresse un cercle de cristal transparent contre l'air glacé.*", "Ce froid restera dehors, j'en ai déjà invoqué assez.", "*referme un cercle protecteur scintillant d'une syllabe murmurée.*" } },
    ARCANE_BLAST = { name = "Déflagration des arcanes", ziel = { "%s, vous ne pourrez pas discuter avec cette énergie.", "La puissance brute n'a nul besoin de flammes pour laisser sa marque.", "*projette une onde dense de lumière violette.*", "%s, l'air lui-même s'apprête à vous frapper." }, gruppe = { "La puissance brute n'a nul besoin de flammes pour laisser sa marque.", "*projette une onde dense de lumière violette.*", "Une impulsion brève fait trembler tout le motif.", "*décale un glyphe flottant d'un cheveu et en écoute le bourdonnement.*" } },
    ARCANE_WRATH = { name = "Courroux des arcanes", ziel = { "%s, ma patience était votre dernière protection.", "Les arcanes répondent à la sottise avec vigueur.", "*tord deux sceaux flottants jusqu'à faire jaillir une décharge lumineuse.*", "%s, vous avez mis la patience des arcanes à l'épreuve." }, gruppe = { "Les arcanes répondent à la sottise avec vigueur.", "*tord deux sceaux flottants jusqu'à faire jaillir une décharge lumineuse.*", "Quand les runes s'emportent, le mana lui-même se fait attentif.", "*décale un glyphe flottant d'un cheveu et en écoute le bourdonnement.*" } },
    ARCANE_POWER = { name = "Pouvoir des arcanes", ziel = {  }, gruppe = { "Il est temps pour la théorie de prouver sa véritable valeur.", "*ouvre les mains tandis que des cercles runiques accélèrent leur rotation.*", "Pour un instant, j'ouvre les vannes plus grand que d'ordinaire.", "*décale un glyphe flottant d'un cheveu et en écoute le bourdonnement.*" } },
    PRESENCE_OF_MIND = { name = "Présence spirituelle", ziel = {  }, gruppe = { "Certaines pensées vont plus vite que la parole.", "*s'immobilise un instant comme si tous les chemins devenaient visibles à la fois.*", "La pensée arrive avant même que mes mains se mettent en mouvement.", "*décale un glyphe flottant d'un cheveu et en écoute le bourdonnement.*" } },
    BLAST_WAVE = { name = "Vague explosive", ziel = { "%s, vous êtes trop près de mon centre.", "Quand l'air riposte, mieux vaut prendre ses distances.", "*frappe dans ses mains et libère une onde de choc brûlante.*", "%s, je vous conseille de vous préparer à cette vague de chaleur." }, gruppe = { "Quand l'air riposte, mieux vaut prendre ses distances.", "*frappe dans ses mains et libère une onde de choc brûlante.*", "L'air lui-même devient un poing de chaleur.", "*tend des fils incandescents jusqu'à ce qu'ils s'animent d'eux-mêmes.*" } },
    COMBUSTION = { name = "Combustion", ziel = {  }, gruppe = { "Aujourd'hui, chaque braise donnera sa dernière étincelle.", "*attire la chaleur alentour dans une flamme unique et vacillante.*", "Je veille sur la braise jusqu'à ce qu'elle éclipse tout le reste.", "*tend des fils incandescents jusqu'à ce qu'ils s'animent d'eux-mêmes.*" } },
    FROSTFIRE_BOLT = { name = "Éclair de givrefeu", ziel = { "%s, choisissez vite entre le givre et les flammes.", "Une contradiction ? Seulement pour un mauvais mage.", "*entrelace des éclats de glace bleus et des filaments de feu rouges en un projectile.*", "%s, vous sentirez à la fois l'hiver et la fournaise." }, gruppe = { "Une contradiction ? Seulement pour un mauvais mage.", "*entrelace des éclats de glace bleus et des filaments de feu rouges en un projectile.*", "Le givre et la flamme ne se contredisent qu'en apparence.", "*tend des fils incandescents jusqu'à ce qu'ils s'animent d'eux-mêmes.*" } },
    FELFIRE = { name = "Gangrefeu", ziel = { "%s, même cette flamme étrangère obéit à un sceau bien tracé.", "Le feu vert exige davantage de prudence, pas moins de réflexion.", "*enferme une flamme verte instable dans un étroit anneau runique.*", "%s, même une flamme étrangère peut recevoir une direction." }, gruppe = { "Le feu vert exige davantage de prudence, pas moins de réflexion.", "*enferme une flamme verte instable dans un étroit anneau runique.*", "Cette flamme verte exige une main exceptionnellement sûre.", "*tend des fils incandescents jusqu'à ce qu'ils s'animent d'eux-mêmes.*" } },
    ICE_LANCE = { name = "Lance de glace", ziel = { "%s, un seul éclat suffira pour toute réponse.", "La glace n'a pas besoin d'être grande pour être tranchante.", "*condense du givre scintillant en une lance aussi fine qu'une aiguille.*", "%s, le plus petit glaçon peut trouver la moindre faille." }, gruppe = { "La glace n'a pas besoin d'être grande pour être tranchante.", "*condense du givre scintillant en une lance aussi fine qu'une aiguille.*", "Une lance de glace n'a pas besoin d'être grande, seulement implacablement droite.", "*expire lentement, dessinant des lignes de cristaux argentés dans l'air.*" } },
    FROST_BLAST = { name = "Explosion de givre", ziel = { "%s, cet hiver arrive sans avertissement.", "Le froid en un seul battement de cœur implacable.", "*déchaîne une violente rafale de givre depuis son poing ouvert.*", "%s, vous n'entendrez pas le givre avant qu'il ne frappe." }, gruppe = { "Le froid en un seul battement de cœur implacable.", "*déchaîne une violente rafale de givre depuis son poing ouvert.*", "Le froid ne frappe pas, il vole toute chaleur à l'instant.", "*expire lentement, dessinant des lignes de cristaux argentés dans l'air.*" } },
    COLD_SNAP = { name = "Morsure du froid", ziel = {  }, gruppe = { "Le temps n'est qu'une variable de plus dans l'art du givre.", "*brise un flocon suspendu et réorganise les glyphes de givre.*", "Une seule inspiration, et l'hiver recommence.", "*expire lentement, dessinant des lignes de cristaux argentés dans l'air.*" } },
    CONJURE_MANA_AGATE = { name = "Invocation d'agate de mana", ziel = {  }, gruppe = { "Une agate assez petite pour la poche et assez puissante pour sauver la mise.", "*verse un mince flot de mana dans une agate en formation.*", "Cette agate conserve un petit morceau de demain pour aujourd'hui.", "*rassemble des étincelles éparses en une forme presque tangible.*" } },
    CONJURE_MANA_JADE = { name = "Invocation de jade de mana", ziel = {  }, gruppe = { "Le jade conserve la magie presque aussi patiemment qu'un érudit.", "*dépose une lumière verte dans une gemme de mana parfaitement polie.*", "Le jade garde le mana calme même lorsque mes pensées s'emballent.", "*rassemble des étincelles éparses en une forme presque tangible.*" } },
    CONJURE_MANA_CITRINE = { name = "Invocation de citrine de mana", ziel = {  }, gruppe = { "Une touche de soleil doré pour les heures de fatigue.", "*façonne une citrine lumineuse à partir d'étincelles dorées.*", "La citrine capte une dernière lueur dorée d'énergie arcanique.", "*rassemble des étincelles éparses en une forme presque tangible.*" } },
    CONJURE_MANA_RUBY = { name = "Invocation de rubis de mana", ziel = {  }, gruppe = { "Ce rubis a vu passer plus de mana que certains bibliothécaires.", "*enferme des courants de mana cramoisis dans un rubis étincelant.*", "Dans le rubis, une puissance en réserve attend son heure.", "*rassemble des étincelles éparses en une forme presque tangible.*" } },
    POLYMORPH_COW = { name = "Métamorphose : vache", ziel = { "%s, j'espère que les cloches de vache ne vous dérangent pas.", "Aujourd'hui, quatre pattes et beaucoup d'herbe.", "*dessine la silhouette d'une vache avec des runes doucement lumineuses.*", "%s, j'espère que les pâturages vous sont familiers." }, gruppe = { "Un peu de laine vous irait bien.", "*esquisse la silhouette d'un mouton.*", "Aujourd'hui, quatre pattes et beaucoup d'herbe.", "*dessine la silhouette d'une vache avec des runes doucement lumineuses.*", "La métamorphose est un art précis ; la laine n'est qu'un détail.", "*examine les contours du sort à la recherche de cornes imprévues.*", "Changer de forme un instant peut se montrer fort persuasif.", "Certaines métamorphoses réclament un pâturage particulièrement vaste.", "*tourne une rune et observe les contours se modifier.*" } },
    COMPREHEND_SCROLL = { name = "Compréhension du parchemin", ziel = {  }, gruppe = { "Certains parchemins ne livrent leur sens qu'aux regards patients.", "*lève un parchemin vers la lumière et dénoue ses symboles scellés.*", "L'écriture est ancienne, mais sa logique n'a pas pris une ride.", "*décale un glyphe flottant d'un cheveu et en écoute le bourdonnement.*" } },
    STUDY = { name = "Étude", ziel = {  }, gruppe = { "Qui lance des sorts sans jamais lire reste un apprenti.", "*lisse une annotation dans la marge d'un vieux grimoire.*", "La rune la plus dangereuse est celle qu'on ne comprend qu'à moitié.", "*décale un glyphe flottant d'un cheveu et en écoute le bourdonnement.*" } },
    TELEPORT_STORMWIND = { name = "Téléportation : STORMWIND", ziel = {  }, gruppe = { "Hurlevent n'est qu'à une rune bien tracée.", "*replie l'image des tours blanches en un point de lumière tournoyant.*", "Hurlevent n'est qu'à une pensée claire d'ici.", "*oriente vers la lumière les coordonnées d'une carte flottante.*" } },
    PORTAL_STORMWIND = { name = "Portail : STORMWIND", ziel = {  }, gruppe = { "Un passage vers les portes de Hurlevent. Chacun son tour, je vous prie.", "*ouvre un portail bleu encadré par les remparts de la cité.*", "Une porte vers Hurlevent, de préférence sans douane dans le Néant.", "*oriente vers la lumière les coordonnées d'une carte flottante.*" } },
    TELEPORT_IRONFORGE = { name = "Téléportation : IRONFORGE", ziel = {  }, gruppe = { "Forgefer attend, entre le son des enclumes et la pierre chaude.", "*condense les contours d'une porte de montagne en rune de destination.*", "Les fourneaux de Forgefer sont plus faciles à trouver que ses raccourcis.", "*oriente vers la lumière les coordonnées d'une carte flottante.*" } },
    PORTAL_IRONFORGE = { name = "Portail : IRONFORGE", ziel = {  }, gruppe = { "Si vous sentez la fumée des forges, Forgefer n'est plus loin.", "*ouvre un passage où scintillent un instant des étincelles de forge.*", "Le portail vers Forgefer semble presque sentir le charbon et le minerai.", "*oriente vers la lumière les coordonnées d'une carte flottante.*" } },
